---@class ParkourBuff.Shield : ParkourBuff.Buff
local Shield = Class("Shield", import("Game.Activity.ParkourGame.MainGame.Buff.Buff"))

local CriWareUtils = import('Game.Entry.CriWareUtilsFix')

function Shield:Type()
    return "Shield"
end

function Shield:OnStart()
    --printError("护盾 - OnStart")
    self.super.OnStart(self)
    self.player.conditonState.shieldState = self.ParkourGameUtil.ShieldState.Open
    self.pause = false
    self.player:SetRoleFX( "fx_role_shield", true, false, true ) 
    CriWareUtils.PlaySe( "Audio/sfx_instance_miniworld_parkour", "cat_shield_12001801" )
end

function Shield:OnTick()
    --printError("护盾 - OnTick")
    local invincibleDash = self.player.buffs["InvincibleDash"]
    if isNotNull(invincibleDash) and invincibleDash.alive then
        self.pause = true
    else
        self.pause = false
    end
end

function Shield:TriggerRigister()
    --printError("护盾 - TriggerRigister")
    self.events = CfUtils.EventsDecorated({
        [self.ParkourGameUtil.Events.PlayerOnHit] = function()
            if self.pause then
                return
            end
            --printError("护盾 - TriggerRigister -1-")
            self.player.conditonState.shieldState = self.ParkourGameUtil.ShieldState.Closing
            self.alive = false
        end
    })
end

function Shield:OnEnd()
    self.super.OnEnd(self)
    --printError("护盾 - OnEnd")
    self.player:SetRoleFX( "fx_role_shield", false, false, true ) 
    --CriWareUtils.Stop( "Audio/sfx_instance_miniworld_parkour", "cat_shield_12001801" )
end

return Shield